function addScore(id){if(!state.done.has(id)){state.done.add(id);state.score++;updateScore();saveLocal()}}
function updateScore(){ $("#score").textContent=state.score; $("#maxScore").textContent=calcMax(); }
function calcMax(){return GRAMMAR.reduce((n,g)=>n+g.quiz.length,0)+QUESTION_QUIZ.length+RELATIVE_QUIZ.length+PREP_QUIZ.length+WORD_ORDERS.length}
function speak(text){if(!("speechSynthesis" in window))return alert("Audio is not available in this browser.");speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=$("#accentSelect").value;u.rate=.9;speechSynthesis.speak(u)}
function bindAudio(){$$('.audio[data-say]').forEach(b=>b.onclick=()=>speak(b.dataset.say));$$('.model-audio').forEach(b=>b.onclick=()=>{const el=document.getElementById(b.dataset.target);speak(el.textContent.trim())})}
function modeApply(){state.mode=$("#modeSelect").value;document.body.classList.toggle("exam-mode",state.mode==="exam");document.body.classList.toggle("practice-mode",state.mode==="practice");document.body.classList.remove("review-mode");$("#reportMode").textContent=state.mode==="exam"?"Exam":"Practice";saveLocal()}
function supportApply(){document.body.classList.toggle("support-fr",$("#supportSelect").value==="fr")}

function renderGrammarTabs(){const host=$("#grammarTabs");host.innerHTML=GRAMMAR.map(g=>`<button data-g="${g.id}" class="${g.id===state.grammar?'active':''}">${g.title}</button>`).join("");$$('[data-g]',host).forEach(b=>b.onclick=()=>{state.grammar=b.dataset.g;renderGrammarTabs();renderGrammarLesson()})}
function renderGrammarLesson(){const g=GRAMMAR.find(x=>x.id===state.grammar);const host=$("#grammarLesson");host.innerHTML=`<div class="grammar-card"><div class="section-head"><div><span class="tag">${g.title}</span><h3>${g.rule}</h3></div><button class="audio" data-say="${escAttr(g.rule+' '+g.examples.join(' '))}">🔊 Rule + examples</button></div><p class="fr"><strong>FR:</strong> ${g.fr}</p><div class="rule-grid"><div class="rule-cell"><strong>Main form</strong>${g.formula}</div><div class="rule-cell"><strong>Negative</strong>${g.negative}</div><div class="rule-cell"><strong>Question</strong>${g.question}</div><div class="rule-cell"><strong>Signal words</strong>${g.keywords}</div></div><h3>Examples</h3><ul>${g.examples.map(x=>`<li>${x}</li>`).join('')}</ul><div class="quick-tip"><strong>Remember:</strong> ${g.exceptions.join(' ')}</div><h3>Practice immediately</h3><div id="grammarQuiz"></div></div>`;renderQuiz("#grammarQuiz",g.quiz,"g-"+g.id);bindAudio()}
function escAttr(s){return String(s).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}
function renderQuiz(sel,items,prefix){const host=$(sel);host.innerHTML=items.map((q,i)=>`<div class="quiz-item"><div><strong>${i+1}.</strong> ${q[0]}</div><div class="quiz-options">${shuffle(q[2]).map(o=>`<button data-choice="${escAttr(o)}" data-answer="${escAttr(q[1])}" data-index="${i}">${o}</button>`).join('')}</div><div class="hint-inline">💡 ${q[3]}</div><div class="feedback"></div></div>`).join('');$$('button[data-choice]',host).forEach(b=>b.onclick=()=>{const card=b.closest('.quiz-item'),fb=$('.feedback',card),hint=$('.hint-inline',card);if(b.dataset.choice===b.dataset.answer){b.classList.add('correct-choice');fb.textContent='✅ Correct — '+items[+b.dataset.index][3];fb.className='feedback correct';hint.classList.remove('show');addScore(prefix+b.dataset.index)}else{b.classList.add('wrong-choice');fb.textContent='❌ Not yet. Try another answer.';fb.className='feedback incorrect';hint.classList.add('show')}})}

function renderVocab(){const cats=[...new Set(VOCAB.map(v=>v[0]))];const sel=$("#vocabCategory");sel.innerHTML='<option value="all">All categories</option>'+cats.map(c=>`<option>${c}</option>`).join('');sel.onchange=drawVocab;drawVocab()}
function drawVocab(){const cat=$("#vocabCategory").value||"all",list=VOCAB.filter(v=>cat==="all"||v[0]===cat);$("#vocabGrid").innerHTML=list.map(v=>`<article class="vocab-card"><small>${v[0]}</small><div class="word">${v[1]}</div><div class="frline"><strong>FR:</strong> ${v[2]}</div><div class="frline">${v[3]}</div><div class="example"><em>${v[4]}</em></div><div class="v-actions"><button class="btn mini reveal-card">Reveal</button><button class="audio" data-say="${escAttr(v[1]+'. '+v[4])}">🔊</button></div></article>`).join('');$$('.reveal-card').forEach(b=>b.onclick=()=>b.closest('.vocab-card').classList.toggle('revealed'));bindAudio()}

function renderTasks(){$("#taskChoices").innerHTML=TASKS.map((t,i)=>`<label><input type="checkbox" value="${escAttr(t)}"> ${t}</label>`).join('')}
function buildIntro(){const name=$("#firstName").value.trim()||"…",loc=$("#locationInput").value.trim()||"in La Chevrolière, near Nantes",goal=$("#goalInput").value.trim()||"feel more confident and autonomous when I travel abroad",sit=$("#situationInput").value==="custom"?"My situation is changing at the moment.":$("#situationInput").value,topics=$$('#introTopics input:checked').map(x=>x.value);const career=topics.includes("my childcare career"),family=topics.includes("my family"),dance=topics.includes("African dance and percussion"),other=topics.includes("walking, gardening, reading, knitting and sewing"),past=topics.includes("Scotland, Cambodia and Vietnam"),future=topics.includes("a future trip to Guadeloupe");let hobbies=[];if(dance)hobbies.push("African dance and percussion");if(other)hobbies.push("walking, gardening, reading, knitting and sewing");let hobbyText=hobbies.length?hobbies.slice(0,-1).join(', ')+(hobbies.length>1?' and ':'')+hobbies.slice(-1):"travelling";const a2=`Hello. My name is ${name}. I live ${loc}. ${career?'I worked as a childcare assistant in hospitals, nurseries and private homes. ':''}${sit} ${family?'I am married and I have three adult children and a granddaughter. ':''}In my free time, I enjoy ${hobbyText}. I am learning English because I want to ${goal}.`;const b1=`Hello. My name is ${name}, and I live ${loc}. I was born in the north of France, spent two years in Senegal and later lived near Paris for many years. ${career?'I worked as a childcare assistant in hospitals, nurseries and private homes. ':''}${sit} ${family?'I am married, I have three adult children, and I also spend time regularly with my granddaughter. ':''}I especially enjoy ${hobbyText}. ${past?'I have travelled to Scotland, Cambodia and Vietnam, which is one reason English is useful for me. ':''}My main goal is to ${goal}.${future?' I am also planning a trip to Guadeloupe.':''}`;const stretch=`Hello. My name is ${name}, and I live ${loc}. My life has taken me through several places: I was born in northern France, spent two years in Senegal and then lived near Paris for about thirty-five years. ${career?'Professionally, I worked as a childcare assistant in hospitals, nurseries and private homes, an experience that taught me patience, observation, communication and adaptability. ':''}${sit} ${family?'Family is very important to me, and I enjoy spending time with my children and granddaughter. ':''}In my free time, I enjoy ${hobbyText}. ${past?'I have also travelled to Scotland, Cambodia and Vietnam, and these experiences have made me want to communicate more independently abroad. ':''}I am continuing to learn English because I want to ${goal}.${future?' I am also looking forward to travelling to Guadeloupe and using my English there.':''}`;$("#introA2").textContent=a2;$("#introB1").textContent=b1;$("#introStretch").textContent=stretch;saveLocal()}
function buildJob(){const title=$("#jobTitle").value.trim()||"childcare assistant",place=$("#workplace").value.trim()||"in hospitals, nurseries and private homes",duration=$("#jobDuration").value.trim()||"for many years",tasks=$$('#taskChoices input:checked').map(x=>x.value);const custom=$("#customTask").value.trim();if(custom)tasks.push(custom);const where=place?` ${place}`:"",howlong=duration?` ${duration}`:"";const list=(arr)=>arr.length===1?arr[0]:arr.length>1?arr.slice(0,-1).join(', ')+" and "+arr[arr.length-1]:"";const chosen=list(tasks);$("#jobA2").textContent=`I worked as a ${title}${where}${howlong}.${chosen?` My responsibilities included ${chosen}.`:""} I learned to be patient, attentive and adaptable.`;$("#jobB1").textContent=`My professional background is in childcare. I worked as a ${title}${where}${howlong}.${chosen?` I was responsible for ${chosen}.`:""} The job required patience, observation, clear communication and the ability to adapt to different children and situations. What I learned from this experience is still useful today.`;$("#jobStretch").textContent=`For many years, I worked as a ${title}${where}.${chosen?` My role involved ${chosen}.`:""} Working in different environments taught me to observe carefully, communicate with families and colleagues, stay calm when needs changed and adapt my approach to the individual child. I think the most valuable part of this career was learning that good care depends on both practical skills and human communication.`;saveLocal()}

function renderWordOrders(){const host=$("#wordOrderGrid");host.innerHTML=WORD_ORDERS.map((s,i)=>`<article class="word-card"><h3>Sentence ${i+1}</h3><div class="word-answer" id="woAns${i}"></div><div class="word-bank" id="woBank${i}"></div><div class="buttons"><button class="btn mini" data-resetwo="${i}">↺ Reshuffle</button><button class="audio" data-say="${escAttr(s)}">🔊 Model</button></div><div id="woFb${i}" class="feedback"></div></article>`).join('');WORD_ORDERS.forEach((_,i)=>resetWO(i));$$('[data-resetwo]').forEach(b=>b.onclick=()=>resetWO(+b.dataset.resetwo));bindAudio()}
function resetWO(i){const s=WORD_ORDERS[i],tokens=s.replace(/([.,?])/g,' $1').split(/\s+/).filter(Boolean);const bank=$("#woBank"+i),ans=$("#woAns"+i);ans.innerHTML="";ans.dataset.tokens="[]";$("#woFb"+i).textContent="";let mixed=shuffle(tokens);if(mixed.join(' ')===tokens.join(' '))mixed=mixed.slice(1).concat(mixed[0]);bank.innerHTML=mixed.map((t,k)=>`<button class="word-token" data-token="${escAttr(t)}" data-key="${k}">${t}</button>`).join('');$$('.word-token',bank).forEach(b=>b.onclick=()=>{const arr=JSON.parse(ans.dataset.tokens||"[]");arr.push(b.dataset.token);ans.dataset.tokens=JSON.stringify(arr);const chip=document.createElement('button');chip.className='word-selected';chip.textContent=b.dataset.token;chip.type='button';chip.onclick=()=>resetWO(i);ans.appendChild(chip);b.disabled=true;if(arr.length===tokens.length)checkWO(i)})}
function normalizeTokens(arr){return arr.join(' ').replace(/\s+([.,?])/g,'$1')}
function checkWO(i){const got=normalizeTokens(JSON.parse($("#woAns"+i).dataset.tokens||"[]")),target=WORD_ORDERS[i],fb=$("#woFb"+i);if(got===target){fb.textContent="✅ Correct — excellent sentence structure.";fb.className="feedback correct";addScore("wo"+i)}else{fb.textContent="❌ Not quite. Reshuffle and try again.";fb.className="feedback incorrect"}}

function newScenario(){const level=$("#scenarioLevel").value,list=SCENARIOS[level],s=list[Math.floor(Math.random()*list.length)];state.scenario=s;$("#scenarioTag").textContent=level;$("#scenarioTitle").textContent=s.title;$("#scenarioPrompt").textContent=s.prompt;$("#scenarioFollow").textContent=s.follow;$("#scenarioHintBox").textContent=s.hint;$("#scenarioModelBox").textContent=s.model;$("#scenarioHintBox").classList.add('hidden');$("#scenarioModelBox").classList.add('hidden')}
function startPracticeTimer(seconds){clearInterval(state.practiceTimer);let left=seconds;const el=$("#practiceTimer");const draw=()=>{el.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`};draw();state.practiceTimer=setInterval(()=>{left--;draw();if(left<=0){clearInterval(state.practiceTimer);el.textContent="TIME"}},1000)}

function mockPhaseByLeft(left){const elapsed=900-left;if(elapsed<300)return"questions";if(elapsed<540)return"roleplays";return"discussion"}
function startMock(){clearInterval(state.mock.timer);state.mock={running:true,left:900,index:0,phase:"questions",timer:null};document.body.classList.remove('review-mode');nextMockPrompt(true);drawMockTime();state.mock.timer=setInterval(()=>{state.mock.left--;const p=mockPhaseByLeft(state.mock.left);if(p!==state.mock.phase){state.mock.phase=p;state.mock.index=0;nextMockPrompt(true)}drawMockTime();if(state.mock.left<=0){clearInterval(state.mock.timer);state.mock.running=false;$("#mockQuestion").textContent="Time. Well done — now review your performance.";document.body.classList.add('review-mode')}},1000)}
function drawMockTime(){const l=Math.max(0,state.mock.left);$("#mockTimer").textContent=`${String(Math.floor(l/60)).padStart(2,'0')}:${String(l%60).padStart(2,'0')}`;$("#mockProgressBar").style.width=((900-l)/9)+"%"}
function nextMockPrompt(reset=false){const phase=state.mock.phase||"questions",arr=MOCK[phase];if(!reset)state.mock.index=(state.mock.index+1)%arr.length;const item=arr[state.mock.index%arr.length];const labels={questions:"PHASE 1 · QUESTIONS",roleplays:"PHASE 2 · ROLE-PLAY",discussion:"PHASE 3 · DISCUSSION"};$("#mockPhase").textContent=labels[phase];$("#mockQuestion").textContent=item.q;$("#mockHintBox").textContent=item.hint;$("#mockModelBox").textContent=item.model;$("#mockHintBox").classList.add('hidden');$("#mockModelBox").classList.add('hidden');$("#mockSupport").textContent=phase==="questions"?"Answer in 3–6 sentences. Expect a follow-up question.":phase==="roleplays"?"Interact: ask questions, react and propose a solution.":"Give an opinion, a reason and an example. React to the examiner."}

async function startRecording(kind){if(!navigator.mediaDevices||!window.MediaRecorder)return alert("Recording is not available in this browser.");try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const rec=new MediaRecorder(stream),chunks=[];rec.ondataavailable=e=>chunks.push(e.data);rec.onstop=()=>{const blob=new Blob(chunks,{type:rec.mimeType});const url=URL.createObjectURL(blob);if(kind==='intro'){state.introAudio=url;$("#playIntro").disabled=false;$("#recordStatus").textContent="Recording ready — listen, then try again."}else{state.mockAudioBlob=url;$("#mockPlay").disabled=false}stream.getTracks().forEach(t=>t.stop())};rec.start();state.media=rec;state.stream=stream;if(kind==='intro'){$("#recordIntro").disabled=true;$("#stopIntro").disabled=false;$("#recordStatus").textContent="Recording…"}else{$("#mockRecord").disabled=true;$("#mockStopRecord").disabled=false}}catch(e){alert("Microphone permission was not available.")}}
function stopRecording(kind){if(state.media&&state.media.state!=="inactive")state.media.stop();if(kind==='intro'){$("#recordIntro").disabled=false;$("#stopIntro").disabled=true}else{$("#mockRecord").disabled=false;$("#mockStopRecord").disabled=true}}

function renderRatings(){const labels=["I can introduce myself","I can talk about my past","I can describe my experience","I can explain future plans","I can handle a role-play","I can keep speaking when I hesitate"];$("#selfRatings").innerHTML=labels.map((x,i)=>`<article class="rating-card"><h3>${x}</h3><div class="rating-buttons">${[1,2,3,4,5].map(n=>`<button data-rate="${i}" data-value="${n}">${n}</button>`).join('')}</div></article>`).join('');$$('[data-rate]').forEach(b=>b.onclick=()=>{state.ratings[b.dataset.rate]=+b.dataset.value;$$(`[data-rate="${b.dataset.rate}"]`).forEach(x=>x.classList.toggle('active',+x.dataset.value===+b.dataset.value));saveLocal()})}

const CONNECT_PROGRAMME_OBJECTIVES=[
["P01","Bases en anglais","Révision des structures utiles à l’oral : temps verbaux, auxiliaires, questions WH, prépositions, modaux et vocabulaire fonctionnel."],
["P02","Construire des phrases cohérentes","Construction de réponses de 3 à 6 phrases, remise en ordre de phrases, connecteurs et développement réponse + raison + exemple."],
["P03","Communication écrite","Prises de notes, réponses courtes et traces écrites de préparation ; objectif secondaire dans cette séance principalement orale."],
["P04","Compréhension","Compréhension des questions de l’examinateur, consignes, modèles audio et relances dans les jeux de rôle."],
["P05","Communication professionnelle","Présentation de l’ancien métier de childcare assistant et jeux de rôle en hôpital, crèche et domicile."],
["P06","Discussion sur un sujet professionnel","Développement d’opinions sur la communication avec les parents, l’adaptation aux besoins de l’enfant et les qualités professionnelles."],
["P07","Prononciation","Réactivation des voyelles, terminaisons -ED, consonnes finales, accentuation et intelligibilité pendant les réponses orales."]
];
function adminVal(id){return $(id)?.value?.trim?.()||""}
function adminStatusOptions(selected){return ["Non évalué","Non acquis","En cours d’acquisition","Acquis"].map(x=>`<option ${x===selected?'selected':''}>${x}</option>`).join('')}
function renderConnectObjectives(){const host=$("#connectObjectivesBody");if(!host)return;host.innerHTML=CONNECT_PROGRAMME_OBJECTIVES.map((o,i)=>`<tr><td><strong>${o[0]}</strong></td><td>${o[1]}</td><td><textarea data-connect-proof="${i}">${o[2]}</textarea></td><td><input data-connect-link="${i}" placeholder="Lien / preuve"></td><td><select data-connect-status="${i}">${adminStatusOptions(i===2?'Non évalué':'En cours d’acquisition')}</select></td><td><textarea data-connect-comment="${i}" placeholder="Commentaire"></textarea></td></tr>`).join('');const main=$("#adminMainObjective");main.innerHTML=CONNECT_PROGRAMME_OBJECTIVES.map(o=>`<option value="${o[0]} — ${o[1]}">${o[0]} — ${o[1]}</option>`).join('');main.value="P05 — Communication professionnelle";$$('[data-connect-proof],[data-connect-link],[data-connect-status],[data-connect-comment]').forEach(el=>el.addEventListener('input',updateAdminOutputs));$$('[data-connect-status]').forEach(el=>el.addEventListener('change',updateAdminOutputs))}
function calcRemaining(){const total=parseFloat(adminVal("#adminTotalHours")),before=parseFloat(adminVal("#adminHoursBefore"))||0,dur=parseFloat(adminVal("#adminDuration"))||0;$("#adminHoursRemaining").value=Number.isFinite(total)?Math.max(0,total-before-dur).toFixed(2):""}
function sessionHeaders(){return ["Date","Durée","Objectif principal","Type / activité","Objectifs de la séance","Contenus et activités réalisées","Modalités d’évaluation / preuves","Liens supports / ressources","Niveau d’acquisition","Présence / participation","Notes / bilan","Prochaine étape","Heures restantes"]}
function sessionValues(){calcRemaining();return [adminVal("#adminSessionDate"),adminVal("#adminDuration"),adminVal("#adminMainObjective"),adminVal("#adminActivityType"),adminVal("#adminSessionObjectives"),adminVal("#adminActivities"),adminVal("#adminEvaluation"),adminVal("#adminResourceLink"),adminVal("#adminAcquisition"),adminVal("#adminAttendance"),adminVal("#adminNotes"),adminVal("#adminNextStep"),adminVal("#adminHoursRemaining")]}
function cleanCell(s){return String(s||"").replace(/[\t\r\n]+/g," ").replace(/\s{2,}/g," ").trim()}
