function updateAdminOutputs(){if(!$("#adminSessionRow"))return;calcRemaining();$("#adminSessionRow").value=sessionValues().map(cleanCell).join("\t");$("#adminObjectivesRows").value=objectiveRowsText();$("#adminOneCell").value=`CLOE oral — ${cleanCell(adminVal("#adminSessionObjectives"))} Activités : ${cleanCell(adminVal("#adminActivities"))} Évaluation : ${cleanCell(adminVal("#adminEvaluation"))} Acquisition : ${cleanCell(adminVal("#adminAcquisition"))}. Bilan : ${cleanCell(adminVal("#adminNotes"))} Prochaine étape : ${cleanCell(adminVal("#adminNextStep"))}`}
