function downloadTsv(filename,headers,rows){const content=[headers.join("\t"),rows].join("\n"),blob=new Blob(["\ufeff"+content],{type:"text/tab-separated-values;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function adminData(){return {learner:adminVal("#adminLearner"),training:adminVal("#adminTraining"),certification:adminVal("#adminCertification"),start:adminVal("#adminStartDate"),end:adminVal("#adminEndDate"),total:adminVal("#adminTotalHours"),trainer:adminVal("#adminTrainer"),trainingStatus:adminVal("#adminTrainingStatus"),sessionDate:adminVal("#adminSessionDate"),duration:adminVal("#adminDuration"),hoursBefore:adminVal("#adminHoursBefore"),mainObjective:adminVal("#adminMainObjective"),activityType:adminVal("#adminActivityType"),acquisition:adminVal("#adminAcquisition"),attendance:adminVal("#adminAttendance"),sessionObjectives:adminVal("#adminSessionObjectives"),activities:adminVal("#adminActivities"),evaluation:adminVal("#adminEvaluation"),resource:adminVal("#adminResourceLink"),notes:adminVal("#adminNotes"),nextStep:adminVal("#adminNextStep"),programme:CONNECT_PROGRAMME_OBJECTIVES.map((o,i)=>({proof:$(`[data-connect-proof="${i}"]`)?.value||"",link:$(`[data-connect-link="${i}"]`)?.value||"",status:$(`[data-connect-status="${i}"]`)?.value||"",comment:$(`[data-connect-comment="${i}"]`)?.value||""}))}}
function saveAdminData(){localStorage.setItem(KEY+"_connect_admin",JSON.stringify(adminData()));updateAdminOutputs()}
function loadAdminData(){let d=null;try{d=JSON.parse(localStorage.getItem(KEY+"_connect_admin")||"null")}catch(e){};const map={adminLearner:"learner",adminTraining:"training",adminCertification:"certification",adminStartDate:"start",adminEndDate:"end",adminTotalHours:"total",adminTrainer:"trainer",adminTrainingStatus:"trainingStatus",adminSessionDate:"sessionDate",adminDuration:"duration",adminHoursBefore:"hoursBefore",adminMainObjective:"mainObjective",adminActivityType:"activityType",adminAcquisition:"acquisition",adminAttendance:"attendance",adminSessionObjectives:"sessionObjectives",adminActivities:"activities",adminEvaluation:"evaluation",adminResourceLink:"resource",adminNotes:"notes",adminNextStep:"nextStep"};if(d)Object.entries(map).forEach(([id,k])=>{if(d[k]!==undefined&&$("#"+id))$("#"+id).value=d[k]});if(d?.programme)d.programme.forEach((p,i)=>{if($(`[data-connect-proof="${i}"]`))$(`[data-connect-proof="${i}"]`).value=p.proof||"";if($(`[data-connect-link="${i}"]`))$(`[data-connect-link="${i}"]`).value=p.link||"";if($(`[data-connect-status="${i}"]`))$(`[data-connect-status="${i}"]`).value=p.status||"Non évalué";if($(`[data-connect-comment="${i}"]`))$(`[data-connect-comment="${i}"]`).value=p.comment||""});if(!adminVal("#adminSessionDate"))$("#adminSessionDate").value="2026-10-13";if(!adminVal("#adminResourceLink")&&location.protocol.startsWith("http"))$("#adminResourceLink").value=location.href;updateAdminOutputs()}
function bindAdmin(){renderConnectObjectives();loadAdminData();$$('#connectAdminOverlay input,#connectAdminOverlay textarea,#connectAdminOverlay select').forEach(el=>{el.addEventListener('input',updateAdminOutputs);el.addEventListener('change',updateAdminOutputs)});$("#openConnectAdmin").onclick=()=>{$("#reportOverlay").classList.add("hidden");$("#connectAdminOverlay").classList.remove("hidden");updateAdminOutputs()};$("#closeConnectAdmin").onclick=()=>$("#connectAdminOverlay").classList.add("hidden");$("#copySessionRow").onclick=()=>copyTextValue("#adminSessionRow","Connect Learning session row copied.");$("#copyObjectivesRows").onclick=()=>copyTextValue("#adminObjectivesRows","Connect Learning objective rows copied.");$("#copyOneCell").onclick=()=>copyTextValue("#adminOneCell","One-cell session summary copied.");$("#downloadSessionTsv").onclick=()=>downloadTsv("Nathalie_ConnectLearning_01_Suivi_des_seances.tsv",sessionHeaders(),$("#adminSessionRow").value);$("#downloadObjectivesTsv").onclick=()=>downloadTsv("Nathalie_ConnectLearning_02_Bilan_des_objectifs.tsv",["Code","Objectif","Preuves / éléments observables","Lien source / preuve","Évaluation","Commentaires"],$("#adminObjectivesRows").value);$("#saveAdmin").onclick=()=>{saveAdminData();alert("Connect Learning admin data saved in this browser.")}}

function reportText(){const ratings=Object.entries(state.ratings).map(([k,v])=>`Rating ${+k+1}: ${v}/5`).join('\n');return `Oral Confidence Progress Report\nInteractive score: ${state.score}/${calcMax()}\nMode: ${state.mode}\nCompleted interactive objectives: ${Math.round(state.done.size/calcMax()*100)}%\n${ratings}\nExam-day reminder: ${$("#examReminder").value||'—'}\nTrainer comments: ${$("#trainerComments").value||'—'}`}
function updateReport(){ $("#reportScore").textContent=`${state.score}/${calcMax()}`;$("#reportComplete").textContent=Math.round(state.done.size/calcMax()*100)+"%";$("#reportMode").textContent=state.mode==="exam"?"Exam":"Practice";$("#reportObjectives").innerHTML=OBJECTIVES.map((o,i)=>`<div class="objective"><span>${o}</span><select data-objective="${i}"><option>Not assessed</option><option>Achieved</option><option>In progress</option><option>To review</option></select></div>`).join('');const saved=loadData();if(saved&&saved.objectives)$$("[data-objective]").forEach(s=>s.value=saved.objectives[s.dataset.objective]||"Not assessed");$$('[data-objective]').forEach(s=>s.onchange=saveLocal)}
function downloadReport(){const text=reportText(),blob=new Blob([text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Nathalie-CLOE-Oral-Confidence-Progress-Report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function copyReport(){try{await navigator.clipboard.writeText(reportText());alert('Summary copied.')}catch(e){alert('Copy is not available in this browser.')}}

function loadData(){try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch(e){return null}}
function saveLocal(){const d={score:state.score,done:[...state.done],ratings:state.ratings,mode:state.mode,firstName:$("#firstName")?.value||"",location:$("#locationInput")?.value||"",goal:$("#goalInput")?.value||"",jobTitle:$("#jobTitle")?.value||"",workplace:$("#workplace")?.value||"",jobDuration:$("#jobDuration")?.value||"",customTask:$("#customTask")?.value||"",tasks:$$('#taskChoices input:checked').map(x=>x.value),reminder:$("#examReminder")?.value||"",comments:$("#trainerComments")?.value||"",objectives:$$('[data-objective]').map(s=>s.value)};localStorage.setItem(KEY,JSON.stringify(d))}
function loadLocal(){const d=loadData();if(!d)return;state.score=d.score||0;state.done=new Set(d.done||[]);state.ratings=d.ratings||{};state.mode=d.mode||'practice';$("#modeSelect").value=state.mode;if(d.firstName)$("#firstName").value=d.firstName;if(d.location)$("#locationInput").value=d.location;if(d.goal)$("#goalInput").value=d.goal;if(d.jobTitle)$("#jobTitle").value=d.jobTitle;if(d.workplace)$("#workplace").value=d.workplace;if(d.jobDuration)$("#jobDuration").value=d.jobDuration;if(d.customTask)$("#customTask").value=d.customTask;if(d.reminder)$("#examReminder").value=d.reminder;if(d.comments)$("#trainerComments").value=d.comments;(d.tasks||[]).forEach(t=>{const el=$(`#taskChoices input[value="${CSS.escape(t)}"]`);if(el)el.checked=true});Object.entries(state.ratings).forEach(([i,v])=>$$(`[data-rate="${i}"]`).forEach(x=>x.classList.toggle('active',+x.dataset.value===+v)));updateScore();modeApply()}
function resetAll(){if(!confirm('Reset this lesson and saved progress?'))return;localStorage.removeItem(KEY);location.reload()}

function init(){
  updateScore();renderGrammarTabs();renderGrammarLesson();renderQuiz('#questionQuiz',QUESTION_QUIZ,'q-');renderQuiz('#relativeQuiz',RELATIVE_QUIZ,'r-');renderQuiz('#prepQuiz',PREP_QUIZ,'p-');renderVocab();renderTasks();renderWordOrders();renderRatings();bindAudio();
  loadLocal();
  $$('[data-scroll]').forEach(b=>b.onclick=()=>$(b.dataset.scroll).scrollIntoView({behavior:'smooth'}));
  $("#modeSelect").onchange=modeApply;$("#supportSelect").onchange=supportApply;$("#stopAudio").onclick=()=>{if("speechSynthesis" in window)speechSynthesis.cancel()};$("#resetAll").onclick=resetAll;
  $("#buildIntro").onclick=buildIntro;$("#clearIntro").onclick=()=>{$("#firstName").value="";$("#introA2").textContent=$("#introB1").textContent=$("#introStretch").textContent="Build your answer when you are ready."};
  $("#buildJob").onclick=buildJob;$("#jobHint").onclick=()=>$("#jobHintBox").classList.toggle('hidden');
  $("#revealVocab").onclick=()=>$$('.vocab-card').forEach(x=>x.classList.add('revealed'));$("#hideVocab").onclick=()=>$$('.vocab-card').forEach(x=>x.classList.remove('revealed'));
  $("#newScenario").onclick=newScenario;$("#scenarioHint").onclick=()=>{if(state.scenario)$("#scenarioHintBox").classList.toggle('hidden')};$("#scenarioModel").onclick=()=>{if(state.scenario)$("#scenarioModelBox").classList.toggle('hidden')};
  $$('.timer-btn').forEach(b=>b.onclick=()=>startPracticeTimer(+b.dataset.seconds));$("#timerStop").onclick=()=>{clearInterval(state.practiceTimer);$("#practiceTimer").textContent="00:00"};
  $("#startMock").onclick=startMock;$("#nextPrompt").onclick=()=>nextMockPrompt(false);$("#mockHint").onclick=()=>$("#mockHintBox").classList.toggle('hidden');$("#mockModel").onclick=()=>$("#mockModelBox").classList.toggle('hidden');$("#mockAudio").onclick=()=>speak($("#mockQuestion").textContent);
  $("#recordIntro").onclick=()=>startRecording('intro');$("#stopIntro").onclick=()=>stopRecording('intro');$("#playIntro").onclick=()=>{if(state.introAudio)new Audio(state.introAudio).play()};
  $("#mockRecord").onclick=()=>startRecording('mock');$("#mockStopRecord").onclick=()=>stopRecording('mock');$("#mockPlay").onclick=()=>{if(state.mockAudioBlob)new Audio(state.mockAudioBlob).play()};
  const openReport=()=>{$("#reportOverlay").classList.remove('hidden');updateReport()};$("#openReportTop").onclick=openReport;$("#openReport").onclick=openReport;$("#closeReport").onclick=()=>$("#reportOverlay").classList.add('hidden');$("#downloadReport").onclick=downloadReport;$("#copyReport").onclick=copyReport;$("#printReport").onclick=()=>window.print();$("#saveProgress").onclick=()=>{saveLocal();alert('Progress saved in this browser.')};
  $$('input,textarea,select').forEach(el=>el.addEventListener('change',saveLocal));
  newScenario();nextMockPrompt(true);supportApply();modeApply();bindAdmin();
}
document.addEventListener('DOMContentLoaded',init);
